<div class="row g-3 appointment-summary"><div class="col-sm-6 col-xl"><div class="stat-card accent"><small>Total Appointments</small><strong><?= $summary['total'] ?></strong><span>All records</span></div></div><div class="col-sm-6 col-xl"><div class="stat-card"><small>Today</small><strong><?= $summary['today'] ?></strong><span>Scheduled today</span></div></div><div class="col-sm-6 col-xl"><div class="stat-card"><small>Pending</small><strong><?= $summary['pending'] ?></strong><span>Awaiting confirmation</span></div></div><div class="col-sm-6 col-xl"><div class="stat-card navy"><small>Confirmed</small><strong><?= $summary['confirmed'] ?></strong><span>Ready for service</span></div></div><div class="col-sm-6 col-xl"><div class="stat-card red"><small>Cancelled Appointments</small><strong><?= $summary['cancelled'] ?></strong><span>Closed after appointment date</span></div></div></div>
<div class="admin-panel appointment-filters"><form class="appointment-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="appointments"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search appointment, customer, vehicle..."></label><label>Status<select class="form-select" name="status"><option value="">All statuses</option><?php foreach ($statusLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $filters['status'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>From Date<input class="form-control" type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>To Date<input class="form-control" type="date" name="to" value="<?= e($filters['to']) ?>"></label><div class="appointment-filter-actions"><button class="btn btn-primary" type="submit">Filter</button><a class="btn btn-light" href="index.php?page=admin&amp;section=appointments">Reset</a></div></form></div>
<div class="admin-panel appointment-list"><div class="panel-heading"><h2>Appointment List</h2><span class="text-muted"><?= count($rows) ?> records</span></div><div class="table-responsive"><table class="table admin-table appointment-table"><thead><tr><th>Appointment No.</th><th>Customer</th><th>Vehicle</th><th>Date &amp; Time</th><th>Requested Service</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="7" class="empty-table">No appointments found. Click Add Appointment to create the first record.</td></tr><?php else: foreach ($rows as $row): ?><tr><td><strong><?= e($row['appointment_no']) ?></strong></td><td><strong><?= e($row['customer_name']) ?></strong><small class="d-block text-muted"><?= e($row['contact_number']) ?></small></td><td><?= e($row['vehicle_number'] ?: 'No vehicle selected') ?><?php if ($row['make'] || $row['model']): ?><small class="d-block text-muted"><?= e(trim(($row['make'] ?: '') . ' ' . ($row['model'] ?: ''))) ?></small><?php endif; ?></td><td><?= e($row['appointment_date']) ?><small class="d-block text-muted"><?= e(substr($row['appointment_time'], 0, 5)) ?></small></td><td><?= e($row['requested_service']) ?></td><td><span class="appointment-status appointment-status-<?= e($row['status']) ?>"><?= e($statusLabels[$row['status']]) ?></span></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=appointments-view&amp;id=<?= (int) $row['id'] ?>" title="View appointment" aria-label="View appointment">&#128065;</a><a href="index.php?page=admin&amp;section=appointments-edit&amp;id=<?= (int) $row['id'] ?>" title="Edit appointment" aria-label="Edit appointment">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=appointments-delete" onsubmit="return confirm('Delete this appointment?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><button type="submit" title="Delete appointment" aria-label="Delete appointment">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
